"""`cdpc write` and `cdpc check`: every generated file, written or compared."""

from __future__ import annotations

import difflib
import os
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Optional

from cdpc import contract, manifest, scan, style
from cdpc.repo import CdpcError, EnvError, Paths, license_header, relative_path
from cdpc.scan import LocalMethod


GENERATED_CPP_NOTICE = [
    *license_header("//"),
    "//",
    "// Generated by `tools/cdpc write`. Do not edit by hand.",
    "",
]


CLANG_FORMAT_VERSION = "clang-format version 18."


MAX_DIFF_LINES = 200
# Chunk size for the generated schema literal; stays below the MSVC
# 16380-byte limit for a single string literal.


@dataclass
class Generated:
    """Every generated file's expected text, with what it was built from."""

    outputs: dict[Path, str]
    local_methods: list[LocalMethod]
    upstream_methods: dict[str, set[str]]
    # Legacy declarations left in dispatch domains; see `generate`.
    leftovers: list[LocalMethod]


def generate(
    paths: Paths, contracts: contract.ContractSet, require_primjs: bool
) -> Generated:
    """Build every generated file from valid `contracts` and the sources."""

    upstream = contracts.upstream or contract.load_upstream(paths.upstream_schema)
    upstream_methods = {domain: set() for domain in upstream.domains}
    for domain, name in upstream.commands:
        upstream_methods[domain].add(name)
    existing_manifest = manifest.load_existing_manifest(paths.manifest)
    local_methods = scan.scan_local_methods(
        paths, existing_manifest.method_source, require_primjs=require_primjs
    )
    scopes = scan.scan_domain_scopes(paths.registration_source)
    current_lynx_version = scan.scan_current_lynx_version(paths.lynx_config_source)
    manifest_text = manifest.build_manifest(
        paths,
        local_methods,
        scopes,
        upstream_methods,
        existing_manifest,
        current_lynx_version,
        contracts,
    )
    outputs = {paths.manifest: manifest_text}
    return Generated(outputs, local_methods, upstream_methods, [])


@dataclass
class Finding:
    """One warning or error, with a short phrase for the conclusion line."""

    category: str
    summary: str
    detail: str


class Report:
    """Updated files, then warnings, then errors, then one conclusion line.

    Exit 0 when there is no error. Warnings stay on the conclusion but do not
    fail the command.
    """

    def __init__(self, command: str):
        self.command = command
        self.updated: list[str] = []
        self.warnings: list[Finding] = []
        self.errors: list[Finding] = []

    def warn(self, category: str, summary: str, detail: Optional[str] = None) -> None:
        self.warnings.append(Finding(category, summary, detail or summary))

    def error(self, category: str, summary: str, detail: Optional[str] = None) -> None:
        self.errors.append(Finding(category, summary, detail or summary))

    def finish(self) -> int:
        if self.updated:
            print(style.bold(f"Generated files ({len(self.updated)} updated):"))
        for path in self.updated:
            print(f"  {style.paint('+ Updated', 'green')} {style.paint(path, 'blue')}")
        self.print_findings()
        line = conclusion_line(self.command, len(self.updated), self.errors, self.warnings)
        color = "green" if not self.errors else "red"
        if self.updated or self.warnings or self.errors:
            print()
        print(style.paint(line, "bold", color))
        return 1 if self.errors else 0

    def print_findings(self) -> None:
        for title, findings, formatter in (("Warnings", self.warnings, style.warning),
                                            ("Errors", self.errors, style.error)):
            if not findings:
                continue
            if self.updated or len(findings) > 1:
                print("\n" + style.bold(f"{title} ({len(findings)}):"))
            for index, finding in enumerate(findings):
                if index:
                    print()
                _emit(formatter, finding.detail)


def conclusion_line(
    command: str, updated: int, errors: list[Finding], warnings: list[Finding]
) -> str:
    """The single trailing line of `write` and `check`."""

    mark = "✓" if not errors else "✗"
    parts: list[str] = []
    if updated:
        noun = "file" if updated == 1 else "files"
        parts.append(f"updated {updated} {noun}")
    elif not errors:
        parts.append("up to date")
    if errors:
        noun = "error" if len(errors) == 1 else "errors"
        parts.append(f"{len(errors)} {noun} ({_summaries(errors)})")
    elif warnings:
        noun = "warning" if len(warnings) == 1 else "warnings"
        parts.append(f"{len(warnings)} {noun}")
    return f"{mark} {command}: {'; '.join(parts)}"


def _summaries(findings: list[Finding]) -> str:
    seen: list[str] = []
    for finding in findings:
        # Paths and repair commands belong in the diagnostic, not the conclusion.
        summary = finding.summary if len(finding.summary) <= 64 else finding.category
        if summary not in seen:
            seen.append(summary)
    shown = []
    for summary in seen[:4]:
        if shown and len(", ".join([*shown, summary])) > 80:
            break
        shown.append(summary)
    text = ", ".join(shown)
    extra = len(seen) - len(shown)
    if extra:
        text += f", +{extra} more"
    return text


def _emit(prefix, text: str) -> None:
    lines = text.splitlines() or [""]
    print(prefix(lines[0]))
    if len(lines) > 1:
        print(style.format_blocks("\n".join(lines[1:])))


def _contract_summary(error: str) -> str:
    if "TODO(cdpc)" in error:
        name = error.split(":", 1)[0].rsplit("/", 1)[-1]
        return f"TODO(cdpc) in {name}"
    first = error.split("\n", 1)[0]
    return first if len(first) <= 80 else first[:77] + "..."


def _leftover_summary(leftovers: list[LocalMethod]) -> str:
    domains = sorted({item.domain for item in leftovers})
    return "legacy leftovers in " + ", ".join(domains)


def _absorb_contracts(report: Report, contracts: contract.ContractSet) -> bool:
    """Record contract warnings and errors. Returns True when errors block generation."""

    for warning in contracts.warnings:
        report.warn("advisory", warning.split("\n", 1)[0], warning)
    for error in contracts.errors:
        report.error("contract", _contract_summary(error), error)
    return bool(contracts.errors)


def write(paths, contracts, require_primjs, dry_run=False):
    report = Report("write")
    if _absorb_contracts(report, contracts):
        return report.finish()
    generated = generate(paths, contracts, require_primjs)
    for path, expected in generated.outputs.items():
        actual = path.read_text() if path.exists() else ""
        if actual == expected:
            continue
        if dry_run:
            print("".join(difflib.unified_diff(actual.splitlines(True), expected.splitlines(True), fromfile=str(path), tofile=str(path))), end="")
        else:
            path.write_text(expected, encoding="utf-8")
            report.updated.append(relative_path(paths, path))
    return report.finish()


def check(paths, contracts, require_primjs):
    report = Report("check")
    if _absorb_contracts(report, contracts):
        return report.finish()
    generated = generate(paths, contracts, require_primjs)
    collect_output_errors(report, paths, generated.outputs, generated.local_methods, generated.upstream_methods)
    return report.finish()


def collect_output_errors(
    report: Report,
    paths: Paths,
    outputs: dict[Path, str],
    local_methods: list[LocalMethod],
    upstream_methods: dict[str, set[str]],
) -> None:
    """Record stale or missing generated files and missing docs on `report`."""

    for path, expected in outputs.items():
        relative = relative_path(paths, path)
        if not path.exists():
            report.error(
                "stale",
                f"missing generated file {relative}",
                f"DevTool CDP generated file is missing: {relative}",
            )
            continue
        actual = path.read_text(encoding="utf-8")
        if actual == expected:
            continue
        diff = list(
            difflib.unified_diff(
                actual.splitlines(),
                expected.splitlines(),
                fromfile=relative,
                tofile=f"{relative} (expected)",
                lineterm="",
            )
        )
        lines = diff[:MAX_DIFF_LINES]
        if len(diff) > MAX_DIFF_LINES:
            lines.append(f"... {len(diff) - MAX_DIFF_LINES} more diff lines")
        detail = (
            f"DevTool CDP generated file is stale: {relative}\n"
            + style.fence("\n".join(lines), "diff")
            + "\nRun:\n  tools/cdpc write"
        )
        report.error("stale", f"stale generated file {relative}", detail)

    missing_docs = find_missing_custom_docs(
        paths, local_methods, upstream_methods, check_existing_manifest=True
    )
    if missing_docs:
        detail = "DevTool CDP custom docs are missing.\n" + "\n".join(
            f"  - {doc}" for doc in missing_docs
        )
        report.error("contract", "missing custom CDP docs", detail)


def find_missing_custom_docs(
    paths: Paths,
    local_methods: list[LocalMethod],
    upstream_methods: dict[str, set[str]],
    check_existing_manifest: bool,
) -> list[str]:
    missing_docs: list[str] = []
    for method in local_methods:
        if manifest.classify_method(method, upstream_methods) == "standard":
            continue
        doc_file = (
            paths.custom_docs_dir / method.domain / "methods" / f"{method.method}.yaml"
        )
        if not doc_file.exists():
            missing_docs.append(relative_path(paths, doc_file))

    if not check_existing_manifest:
        return missing_docs

    stale_docs = find_docs_without_methods(paths, local_methods)
    if stale_docs:
        raise CdpcError(
            "custom CDP docs without matching metadata method:\n  "
            + "\n  ".join(stale_docs)
        )
    return missing_docs


def find_docs_without_methods(
    paths: Paths, local_methods: Iterable[LocalMethod]
) -> list[str]:
    if not paths.custom_docs_dir.exists():
        return []
    known_methods = {(method.domain, method.method) for method in local_methods}
    stale_docs: list[str] = []
    for doc_file in sorted(paths.custom_docs_dir.glob("*/methods/*.yaml")):
        domain = doc_file.parents[1].name
        method = doc_file.stem
        if (domain, method) not in known_methods:
            stale_docs.append(relative_path(paths, doc_file))
    return stale_docs

